&lt;h3&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;If You Encounter Downed Trees or Power Lines&lt;span style="font-size:14pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;/div&gt;

&lt;div class="ListContainerWrapper SCXW232977702 BCX8" style="margin: 0px; padding: 0px; user-select: text; -webkit-user-drag: none; -webkit-tap-highlight-color: transparent; position: relative; font-family: &amp;quot;Segoe UI&amp;quot;, &amp;quot;Segoe UI Web&amp;quot;, Arial, Verdana, sans-serif; font-size: 12px; background-color: rgb(255, 255, 255);"&gt;
&lt;ul&gt;
     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;strong&gt;Never&lt;/strong&gt;&lt;span style="font-size:12pt"&gt; touch or move downed lines&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
