     &lt;li&gt;
     &lt;p&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;&lt;span style="font-size:12pt"&gt;Report hazards to local authorities&lt;/span&gt;&lt;span style="font-size:12pt"&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
